@page "/settings"
@using sv_5e2da45538ed4ad48c80611371e26225.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-page d-flex">
    <div class="settings-sidebar-container">
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />
    </div>
    <div class="settings-content flex-grow-1 p-4">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-page {
    min-height: calc(100vh - 60px);
}

.settings-sidebar-container {
    width: 220px;
    border-right: 1px solid #dee2e6;
    min-height: calc(100vh - 60px);
}

.settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0;
    padding: 0.75rem 1.25rem;
    text-align: left;
    width: 100%;
    border: none;
    background: none;
    transition: background-color 0.15s;
}

.settings-sidebar .nav-link:hover {
    background-color: #f8f9fa;
}

.settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
    font-weight: 500;
}

.settings-content {
    max-width: 900px;
}

